steps.prompt:
请分别搜索下面每个关键词在过去{{inputs.window}}内的最新公开报道、公告或博客文章：
{{inputs.keywords}}
排除包含这些词的结果：{{inputs.exclude}}
每个关键词最多 5 条，只保留和关键词本身直接相关的内容。每条给出：对应的关键词、标题、原文链接（必须来自搜索结果）、来源名、发布时间（ISO 日期，不确定就留空）、一句话摘要（不超过 50 字）。

steps.source:
export default async function run(input) {
  const seen = new Set(input.n1 || []);
  const norm = (u) => {
    try {
      const x = new URL(u);
      [...x.searchParams.keys()].forEach((k) => { if (k.startsWith('utm_') || k === 'ref') x.searchParams.delete(k); });
      x.hash = '';
      const host = x.hostname.replace(/^www\./, '');
      return (host + x.pathname.replace(/\/$/, '') + x.search).toLowerCase();
    } catch { return null; }
  };
  const out = [];
  const thisRun = new Set();
  for (const it of (input.n2 && input.n2.items) || []) {
    const key = norm(it.url);
    if (!key || thisRun.has(key)) continue;
    thisRun.add(key);
    out.push({ ...it, _key: key, isNew: !seen.has(key) });
  }
  out.sort((a, b) => (b.isNew - a.isNew) || String(b.publishedAt).localeCompare(String(a.publishedAt)));
  const merged = [...out.map((i) => i._key), ...seen].filter((v, i, a) => a.indexOf(v) === i).slice(0, 500);
  return {
    items: out.map((i) => ({ title: i.title, url: i.url, subtitle: i.summary, source: i.source, badge: i.isNew ? '新' : '', meta: i.keyword + (i.publishedAt ? ' · ' + i.publishedAt.slice(0, 10) : ''), _unverified: i._unverified })),
    seen: merged,
    newCount: out.filter((i) => i.isNew).length
  };
}
